# ---- THE ALIGNMENT ENGINE ACROSS BOOKS — Exod 29 (the spec) to Lev 8 (the run), block by block ----
def norm(w):
    if w in ('את', 'ואת', 'אתו', 'אתם', 'אתה'): return None
    if w[:1] == 'ו' and len(w) > 3: w = w[1:]
    if w[:1] == 'ה' and len(w) > 3: w = w[1:]
    return w
def bag(k):
    return set(x for x in map(norm, toks(*k)) if x)
BLOCKS = [('inventory', ('Exod', 29, 1, 3), ('Lev', 8, 2, 2)), ('washing', ('Exod', 29, 4, 4), ('Lev', 8, 6, 6)), ('dressing', ('Exod', 29, 5, 9), ('Lev', 8, 7, 13)),
          ('bull', ('Exod', 29, 10, 14), ('Lev', 8, 14, 17)), ('ram_olah', ('Exod', 29, 15, 18), ('Lev', 8, 18, 21)), ('ram_miluim', ('Exod', 29, 19, 28), ('Lev', 8, 22, 30)),
          ('meal', ('Exod', 29, 31, 34), ('Lev', 8, 31, 32)), ('seven_days', ('Exod', 29, 35, 37), ('Lev', 8, 33, 36))]
NUM = {'אחד', 'אחת', 'שני', 'שתי', 'שנים', 'שלש', 'שלשה', 'ארבע', 'חמש', 'שש', 'שבע', 'שבעת', 'עשר', 'עשרה', 'עשרים', 'מאה', 'מאת', 'אלף'}
ALIGN = {}
for name, (sb, sc, sa, sz), (rb, rc, ra, rz) in BLOCKS:
    spec = [(sb, sc, v) for v in range(sa, sz + 1)]; rv = [(rb, rc, v) for v in range(ra, rz + 1)]
    m = {}
    for k in rv:
        best = max(spec, key=lambda s: len(bag(k) & bag(s)) / max(1, len(bag(k) | bag(s))))
        j = len(bag(k) & bag(best)) / max(1, len(bag(k) | bag(best)))
        if j >= 0.3: m.setdefault(best, []).append(k)
    ns = collections.Counter(w.lstrip('ו') for s in spec for w in toks(*s) if w.lstrip('ו') in NUM)
    nr = collections.Counter(w.lstrip('ו') for k in rv for w in toks(*k) if w.lstrip('ו') in NUM)
    ALIGN[name] = {'spec': len(spec), 'run': len(rv), 'matched': len(m), 'run_matched': sum(len(x) for x in m.values()),
                   'dropped': ['%d:%d' % s[1:] for s in spec if s not in m], 'numerals_equal': ns == nr}
A_TOTAL = (sum(a['spec'] for a in ALIGN.values()), sum(a['run'] for a in ALIGN.values()), sum(a['matched'] for a in ALIGN.values()),
           sum(a['run_matched'] for a in ALIGN.values()), sum(len(a['dropped']) for a in ALIGN.values()))
A_DROPPED = [d for a in ALIGN.values() for d in a['dropped']]
A_NUM_EQ = sorted(n for n, a in ALIGN.items() if a['numerals_equal'])
RUN_UNBLOCKED = ['8:1', '8:3', '8:4', '8:5', '8:10', '8:11']          # the run's verses no block of the spec holds
SPEC_UNBLOCKED = ['29:29', '29:30'] + ['29:%d' % v for v in range(38, 47)]   # the spec's verses no block of the run holds
assert A_TOTAL == (35, 32, 14, 15, 21), A_TOTAL
assert A_NUM_EQ == ['bull', 'meal', 'ram_olah', 'washing'], A_NUM_EQ
A_BLOCK_PAIRS = [(n, ALIGN[n]['spec'], ALIGN[n]['run'], ALIGN[n]['matched']) for n, _, _ in BLOCKS]
print('alignment across books: spec %d verses, run %d; spec matched %d, run matched %d, dropped %d — %s; numerals equal in %s; run verses outside every block %s; spec verses outside every block %s'
      % (A_TOTAL + (A_DROPPED, A_NUM_EQ, RUN_UNBLOCKED, SPEC_UNBLOCKED)))

