def build(q):
    if q == 'alignment':
        return cell(A_TOTAL, I, "the alignment engine ACROSS BOOKS: (spec verses, run verses, spec matched, run matched, dropped) = %s — every Lev 8 verse of a block aligned to its Exod 29 verse by normalized token overlap at threshold 0.3: the run rewrites the second person as the third ('you shall take' %d times in the spec, 'and he took' %d in the run), so the block-level correspondence holds while the token-level match is low — the grammar artifact E3 recorded, at its widest" % (A_TOTAL, sum(toks('Exod', 29, v).count('ולקחת') for v in range(1, 47)), sum(toks('Lev', 8, v).count('ויקח') for v in range(1, 37))), [FX.NONE])
    if q == 'blocks':
        return cell(A_BLOCK_PAIRS, I, "the eight blocks (name, spec verses, run verses, matched): %s — the bull and the two rams carry the matches; the persons, the washing, the seven days none" % (A_BLOCK_PAIRS,), [FX.NONE])
    if q == 'dropped':
        return cell(A_DROPPED, I, "the twenty-one spec verses no run verse matched at the threshold: %s" % (A_DROPPED,), [FX.NONE])
    if q == 'run_unblocked':
        return cell(RUN_UNBLOCKED, I, "the run's verses OUTSIDE every block of the spec: %s — the heading (8:1), THE ASSEMBLY (8:3-5: 'gather all the congregation to the door' — the spec never convenes the people), and THE TABERNACLE'S ANOINTING (8:10-11 — the run of ANOTHER spec, 30:26-29, inserted into this one's run)" % (RUN_UNBLOCKED,), [FX.NONE])
    if q == 'spec_unblocked':
        return cell(SPEC_UNBLOCKED, I, "the spec's verses OUTSIDE every block of the run: %s — the succession (a law for the generations) and the tamid and the Presence (the standing machinery the seven days install but do not run)" % (SPEC_UNBLOCKED,), [FX.NONE])
    if q == 'numerals_equal':
        return cell(A_NUM_EQ, I, "the blocks whose numeral multisets match: %s — the dressing's differ (the run adds none but drops 29:9's grouping), the installation ram's by the spec's 'one' loaf and 'one' cake and 'one' wafer against the run's" % (A_NUM_EQ,), [FX.NONE])
    if q == 'person_shift':
        return cell((11, 8), I, "'and you shall take' (ולקחת) %d times in the spec; 'and he took' (ויקח) %d in the run — the one grammatical shift that accounts for most of the dropped verses" % (sum(toks('Exod', 29, v).count('ולקחת') for v in range(1, 47)), sum(toks('Lev', 8, v).count('ויקח') for v in range(1, 37))), [FX.NONE])
    if q == 'spec_cites_itself':
        return cell(1, I, "the spec's one citation token: 29:35 'according to all I COMMANDED you' (%d) — against the run's eleven command-tokens and five full stamps: the run cites, the spec commands" % (sum(toks('Exod', 29, v).count('צויתי') for v in range(1, 47)),), ['inspected_as_commanded'])
    if q == 'headline':
        return cell('the_spec_run_delta_is_where_the_tradition_argues', M, "THE HEADLINE (Yoma 5b:9): the run SPLITS the spec's grouped verb (29:9 'gird THEM' -> 8:7 'girded HIM', 8:13 'girded THEM') and the dressing-order dispute runs on exactly that delta; the run INSERTS another spec's run (8:10-11) and ADDS its own limiters (8:35); the run DROPS the law clauses and the promises (the dues, the succession, the tamid, the Presence) — move M-22's family, a fourth form: the delta", [FX.NONE])
    if q == 'world':
        return cell(SCENE, I, "THE SCENE on the world engine — Lev 8's tape through this spec's daemon: (names borne, judgment borne, entry announced, plate propitiates — THE FOUR USE ENTRIES THE VESTMENTS SPEC PROMISED, fired at the dressing; hands laid x3; blood on the extremities x2; the altar purged; the breast waved; the due to Moses; the garments consecrated; the office invested; the remainder burned; the confinement; the anointings; events)", ['names_borne', 'judgment_borne', 'entry_announced', 'plate_propitiates', 'hand_laid', 'blood_on_extremities', 'altar_purged', 'waved', 'due_to_priest', 'consecrated', 'invested_office', 'burn_remainder', 'confined_seven_days', 'anointed'])
    return cell('no_case', I, '', [FX.NONE])

